104	export default {
105	  private: {
106	    isDark: false,
107	    themeButtonText: "深色模式",
108	    modeLabel: "浅色",
109	    currentTime: "--:--",
110	    booted: false,
111	    activeTab: "news",
112	    activeCategory: "politics",
113	    actionText: "刷新",
114	    loading: false,
115	    hasError: false,
116	    stateText: "",
