180	    console.log("[InfoPlat] theme toggled, isDark: " + this.isDark)
181	  },
182	
183	  showDetail(item) {
184	    if (!item || !item.title) return
185	    router.push({
186	      uri: "pages/detail",
187	      params: {
188	        title: item.title,
189	        description: item.description,
190	        source: item.source,
191	        url: item.url,
192	        isDark: this.isDark
193	      }
194	    })
195	  },
196	
197	  refreshCurrent() {
