284	    this.loadNews(["health"])
285	  },
286	
287	  reloadNews() {
288	    if (this.activeCategory === "tech") {
289	      this.loadNewsTech()
290	    } else if (this.activeCategory === "business") {
291	      this.loadNewsBusiness()
292	    } else if (this.activeCategory === "world") {
293	      this.loadNewsWorld()
294	    } else if (this.activeCategory === "sports") {
295	      this.loadNewsSports()
296	    } else if (this.activeCategory === "entertainment") {
297	      this.loadNewsEntertainment()
298	    } else if (this.activeCategory === "science") {
299	      this.loadNewsScience()
300	    } else if (this.activeCategory === "politics") {
301	      this.loadNewsPolitics()
302	    } else if (this.activeCategory === "health") {
303	      this.loadNewsHealth()
304	    } else {
305	      this.loadNewsPolitics()
306	    }
307	  },
308	
309	  loadNews(categories) {
310	    this.setTab("news")
311	    this.loading = true
312	    this.hasError = false
313	    this.stateText = "正在请求新闻"
314	    this.showNewsContent = false
315	    console.info("[InfoPlat] [Index] Loading news: " + categories.join(","))
316	    getLatestNews({
317	      categories: categories,
318	      pageSize: 50
319	    })
320	      .then((list) => {
321	        this.newsList = list.length > 1 ? list.slice(1) : []
322	        this.leadNews = list.length ? list[0] : emptyNews()
323	        this.loading = false
324	        this.showNewsContent = true
325	      })
326	      .catch((err) => {
327	        this.loading = false
328	        this.hasError = true
329	        this.errorText = "新闻获取失败: " + err.message
330	      })
331	  },
332	
333	  loadWeatherData() {
334	    getWeather("北京").then((info) => {
