export function getExpress(trackingNo) {
  const provider = PROVIDERS.express
  if (!trackingNo) {
    return Promise.resolve({
      ready: false,
      title: "请输入运单号",
      subtitle: provider.name,
      message: "请在下方输入框输入快递运单号进行查询",
      details: ["支持主流快递公司", "输入运单号后点击查询按钮"]
    })
  }

  const query = encodeQuery({
    trackingNo: trackingNo,
    ckey: provider.key
  })
  return request({
    url: provider.url + "?" + query
  }).then((data) => {
    console.info("[InfoPlat] Express response: " + JSON.stringify(data))

    // tmini API 返回格式处理
    if (data && data.code === 200 && data.data) {
      const expressData = data.data
      const list = expressData.list || expressData.info || []
      const first = list.length ? list[0] : null
      return {
        ready: true,
        title: trackingNo,
        subtitle: expressData.company || expressData.com || "快递公司",
        message: first ? (first.remark || first.status || first.context) : "物流信息暂不可用",
        details: list.slice(0, 5).map((item) => {
          const time = item.time || item.ftime || item.datetime || ""
          const desc = item.remark || item.status || item.context || ""
          return time + " " + desc
        })
      }
    } else {
      // API 返回错误或格式不符
      const errorMsg = data && data.msg ? data.msg : "查询失败，请检查运单号"
      return {
        ready: false,
        title: trackingNo,
        subtitle: "查询失败",
        message: errorMsg,
        details: ["请确认运单号是否正确", "或稍后重试"]
      }
    }
  }).catch((err) => {
    console.error("[InfoPlat] Express query failed: " + err.message)
    return {
      ready: false,
      title: trackingNo,
      subtitle: "查询出错",
      message: "网络请求失败: " + err.message,
      details: ["请检查网络连接", "或稍后重试"]
    }
  })
}

