export function getExpress(trackingNo) {
  const provider = PROVIDERS.express
  if (!trackingNo) {
    return Promise.resolve({
      ready: false,
      title: "请输入运单号",
      subtitle: provider.name,
      message: "请在下方输入框输入快递运单号进行查询",
      details: ["支持主流快递公司", "输入运单号后点击查询按钮"]
    })
  }

  const query = encodeQuery({
    trackingNo: trackingNo,
    ckey: provider.key
  })
  return request({
    url: provider.url + "?" + query
  }).then((data) => {
    console.info("[InfoPlat] Express response: " + JSON.stringify(data))

    // tmini API 返回格式处理
    // 成功状态码: "0000000000"
    if (data && data.code === "0000000000" && data.data) {
      const expressData = data.data
      const packageList = expressData.packageInfoList || []

      if (packageList.length === 0) {
        return {
          ready: false,
          title: trackingNo,
          subtitle: "未找到物流信息",
          message: "该运单号暂无物流信息",
          details: ["请确认运单号是否正确", "或该包裹尚未揽收"]
        }
      }

      // 取第一个包裹的信息
      const pkg = packageList[0]
      const trackingDetails = pkg.trackingDetails || []

      // 格式化时间 (20260512111740 -> 2026-05-12 11:17:40)
      function formatTime(timeStr) {
        if (!timeStr || timeStr.length !== 14) return timeStr
        return timeStr.substring(0, 4) + "-" +
               timeStr.substring(4, 6) + "-" +
               timeStr.substring(6, 8) + " " +
               timeStr.substring(8, 10) + ":" +
               timeStr.substring(10, 12) + ":" +
               timeStr.substring(12, 14)
      }

      // 状态映射
      function getStateText(state) {
        const stateMap = {
          "ACCEPT": "已揽收",
          "TRANSIT": "运输中",
          "DELIVERING": "派送中",
          "FINISH": "已签收",
          "CANCEL": "已取消",
          "abnormal": "异常"
        }
        return stateMap[state] || state
      }

      return {
        ready: true,
        title: trackingNo,
        subtitle: pkg.cpName || pkg.cp || "快递公司",
        message: pkg.operateMessage || "暂无最新状态",
        details: trackingDetails.slice(0, 5).map((item) => {
          return formatTime(item.time) + " " + item.context
        })
      }
    } else {
      // API 返回错误或格式不符
      const errorMsg = data && data.desc ? data.desc : "查询失败，请检查运单号"
      return {
        ready: false,
        title: trackingNo,
        subtitle: "查询失败",
        message: errorMsg,
        details: ["请确认运单号是否正确", "或稍后重试"]
      }
    }
  }).catch((err) => {
    console.error("[InfoPlat] Express query failed: " + err.message)
    return {
      ready: false,
      title: trackingNo,
      subtitle: "查询出错",
      message: "网络请求失败: " + err.message,
      details: ["请检查网络连接", "或稍后重试"]
    }
  })
}

