inputKey(key) {
  this.trackingNo = this.trackingNo + key
  console.info("[InfoPlat] Input key: " + key + ", current: " + this.trackingNo)
},

backspace() {
  if (this.trackingNo.length > 0) {
    this.trackingNo = this.trackingNo.substring(0, this.trackingNo.length - 1)
    console.info("[InfoPlat] Backspace, current: " + this.trackingNo)
  }
},

clearInput() {
  this.trackingNo = ""
  console.info("[InfoPlat] Input cleared")
}

input.new_string:
inputKey(key) {
  // 限制最大输入长度为30个字符
  if (this.trackingNo.length < 30) {
    this.trackingNo += key
  }
},

backspace() {
  if (this.trackingNo.length > 0) {
    this.trackingNo = this.trackingNo.slice(0, -1)
  }
},

clearInput() {
  this.trackingNo = ""
}

